using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using Microsoft.Win32;
namespace ClearSpace {
public static class RuleCenter {
 public static void Show(Window owner,CleanerSettings settings,DiscoveryResult discovery,Action changed,string preview=null,int previewTab=0){
  const string xaml="<Window xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='应用与规则 · by CraZyX' Width='980' Height='700' MinWidth='820' MinHeight='600' WindowStartupLocation='CenterOwner' Background='#161D25' Foreground='#DFEAF2' FontFamily='Microsoft YaHei UI' FontSize='13'><Grid Background='#161D25'><Grid Margin='24'><Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><TextBlock x:Name='Heading' FontSize='24' FontWeight='SemiBold' Foreground='#39C5BB' Text='应用发现与规则库'/><TextBlock x:Name='LibraryState' Grid.Row='1' Margin='0,10,0,16' Foreground='#A7BFCD'/><TabControl Foreground='#DFEAF2' Grid.Row='2' Background='#1D2933' BorderBrush='#344651'><TabItem Header='规则更新'><ScrollViewer VerticalScrollBarVisibility='Auto'><StackPanel Margin='18'><TextBlock Text='HTTPS 规则文件地址' FontSize='15' FontWeight='SemiBold'/><TextBox x:Name='UpdateUrl' Margin='0,10,0,12' Height='34' Background='#25333E' Foreground='#DFEAF2' BorderBrush='#45616C' Padding='8'/><CheckBox x:Name='Automatic' Content='每 7 天自动检查一次（需先填写地址）' Margin='0,0,0,14'/><WrapPanel><Button x:Name='Save' Content='保存设置' Margin='0,0,9,9'/><Button x:Name='Check' Content='检查更新' Margin='0,0,9,9' Background='#39C5BB' Foreground='#083F3A'/><Button x:Name='Import' Content='本地导入' Margin='0,0,9,9'/><Button x:Name='Export' Content='导出当前规则' Margin='0,0,9,9'/><Button x:Name='Rollback' Content='回退上一版' Margin='0,0,9,9'/></WrapPanel><TextBlock Text='云更新只接受已验证发布者签名的规则包。未签名本地规则需确认导入；外部规则只供高级自选。' Foreground='#E4BE81' TextWrapping='Wrap' Margin='0,8,0,18'/><TextBlock Text='便携 / 自定义软件目录' FontSize='15' FontWeight='SemiBold'/><ListBox x:Name='Portable' Background='#202D37' Foreground='#CFDFEB' BorderBrush='#344651' Height='100' Margin='0,10,0,10'/><WrapPanel><Button x:Name='AddPortable' Content='添加目录' Margin='0,0,9,9'/><Button x:Name='RemovePortable' Content='移除所选' Margin='0,0,9,9'/></WrapPanel><TextBlock Text='仅检查所选目录内的程序指纹与明确缓存子目录，不将安装目录整体视为垃圾。修改后重新扫描生效。' Foreground='#91AAB9' TextWrapping='Wrap'/></StackPanel></ScrollViewer></TabItem><TabItem Header='已发现应用'><Grid Margin='14'><Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><TextBox x:Name='AppSearch' Height='33' Padding='8' Margin='0,0,0,12' Background='#25333E' Foreground='#DFEAF2' BorderBrush='#45616C'/><ListBox x:Name='Apps' Grid.Row='1' Background='#1D2933' Foreground='#CFDFEB' BorderBrush='#344651'><ListBox.ItemTemplate><DataTemplate><StackPanel Margin='7'><TextBlock Text='{Binding Name}' FontWeight='SemiBold' FontSize='15'/><TextBlock Text='{Binding Publisher}' Foreground='#9EB6C4'/><TextBlock Text='{Binding Executable}' Foreground='#89A6B8' TextTrimming='CharacterEllipsis'/></StackPanel></DataTemplate></ListBox.ItemTemplate></ListBox><TextBox x:Name='AppEvidence' Grid.Row='2' IsReadOnly='True' TextWrapping='Wrap' MaxHeight='130' VerticalScrollBarVisibility='Auto' Background='#25333E' Foreground='#BBD2DE' BorderThickness='0' Margin='0,12,0,0' Padding='9'/></Grid></TabItem><TabItem Header='备份与恢复'><StackPanel Margin='18'><TextBlock Text='文件备份位置' FontSize='15' FontWeight='SemiBold'/><TextBox x:Name='RecoveryPath' Height='34' Margin='0,10,0,12' Padding='8' Background='#25333E' Foreground='#DFEAF2' BorderBrush='#45616C'/><WrapPanel><Button x:Name='ChooseRecovery' Content='选择备份目录' Margin='0,0,9,9'/><Button x:Name='SaveRecovery' Content='保存备份位置' Margin='0,0,9,9'/><Button x:Name='RestoreFiles' Content='恢复文件备份' Margin='0,0,9,9'/><Button x:Name='Purge' Content='清空所选备份' Margin='0,0,9,9'/></WrapPanel><TextBlock Text='先备份清理为默认方式。备份保存在 C 盘时，需清空备份才会释放对应空间。启发式项目始终先备份；文件备份只支持本机、本账户恢复，现有文件不覆盖。' Foreground='#E4BE81' TextWrapping='Wrap' Margin='0,10,0,0'/></StackPanel></TabItem></TabControl><TextBlock x:Name='Status' Grid.Row='3' Foreground='#39C5BB' TextWrapping='Wrap' Margin='0,14,0,0'/></Grid></Grid></Window>";
  var w=(Window)XamlReader.Parse(xaml);w.Owner=owner;w.Resources=owner.Resources;Func<string,TextBox> text=n=>(TextBox)w.FindName(n);Func<string,Button> button=n=>(Button)w.FindName(n);var store=new RuleStore();var state=(TextBlock)w.FindName("LibraryState");var status=(TextBlock)w.FindName("Status");var automatic=(CheckBox)w.FindName("Automatic");var portable=(ListBox)w.FindName("Portable");var apps=(ListBox)w.FindName("Apps");Action refresh=()=>{var pack=store.Current();state.Text="规则库 "+pack.Pack.Version+" · "+pack.Pack.Rules.Count+" 条应用规则 · "+pack.Trust;portable.ItemsSource=settings.PortableDirectories.ToArray();};refresh();text("UpdateUrl").Text=settings.UpdateUrl;automatic.IsChecked=settings.AutomaticUpdates;text("RecoveryPath").Text=String.IsNullOrEmpty(settings.RecoveryDirectory)?FileRecovery.DefaultDirectory():settings.RecoveryDirectory;var identities=discovery==null?new List<ApplicationIdentity>():discovery.Applications;apps.ItemsSource=identities;text("AppSearch").TextChanged+=(s,e)=>apps.ItemsSource=identities.Where(a=>a.SearchText.IndexOf(text("AppSearch").Text,StringComparison.OrdinalIgnoreCase)>=0).ToList();apps.SelectionChanged+=(s,e)=>{var a=apps.SelectedItem as ApplicationIdentity;text("AppEvidence").Text=a==null?"":RuleStore.Describe(a)+"\n产品："+a.Product+"\n公司："+a.Company+"\n安装目录："+a.InstallDirectory;};if(identities.Count==0)text("AppEvidence").Text="手动开始扫描后会显示应用发现结果。";
  Action save=()=>{string url=text("UpdateUrl").Text.Trim();Uri address;if(url.Length>0&&(!Uri.TryCreate(url,UriKind.Absolute,out address)||address.Scheme!="https"||!String.IsNullOrEmpty(address.UserInfo)))throw new InvalidDataException("请输入 HTTPS 规则地址");if(automatic.IsChecked==true&&url.Length==0)throw new InvalidDataException("自动检查需先填写发布地址");settings.UpdateUrl=url;settings.AutomaticUpdates=automatic.IsChecked==true;settings.Save();};button("Save").Click+=(s,e)=>{try{save();status.Text="设置已保存。";}catch(Exception ex){status.Text=ex.Message;}};
  CancellationTokenSource updateStop=null;bool updating=false,restoring=false;button("Check").Click+=async(s,e)=>{if(updating){updateStop.Cancel();return;}try{save();if(String.IsNullOrWhiteSpace(settings.UpdateUrl)){status.Text="尚未配置发布地址，可先导入本地规则包。";return;}updating=true;updateStop=new CancellationTokenSource();button("Import").IsEnabled=button("Rollback").IsEnabled=false;button("Check").Content="取消更新";status.Text="下载并验证发布者签名…";await Task.Run(()=>store.Update(settings.UpdateUrl,updateStop.Token));refresh();changed();status.Text="规则已更新，重新扫描后生效。";}catch(Exception ex){status.Text="更新未应用："+ex.Message;}finally{updating=false;button("Import").IsEnabled=button("Rollback").IsEnabled=true;button("Check").Content="检查更新";if(updateStop!=null)updateStop.Dispose();}};
  button("Import").Click+=(s,e)=>{var d=new OpenFileDialog{Filter="规则包 (*.json)|*.json",Title="导入应用路径规则"};if(d.ShowDialog(w)!=true)return;try{if(new FileInfo(d.FileName).Length>RuleStore.MaxBytes)throw new InvalidDataException("规则包过大");string raw=File.ReadAllText(d.FileName);var parsed=store.Read(raw,true);if(MessageBox.Show(w,"导入 "+parsed.Pack.Version+" / "+parsed.Pack.Rules.Count+" 条规则，"+parsed.Trust+"。\n全部只供高级自选，重新扫描后生效。", "检查规则来源",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;store.Import(raw,true);refresh();changed();status.Text="导入完成。";}catch(Exception ex){status.Text="未导入："+ex.Message;}};
  button("Export").Click+=(s,e)=>{var d=new SaveFileDialog{Filter="规则包 (*.json)|*.json",FileName="ClearSpace-rules.json"};if(d.ShowDialog(w)==true)try{File.WriteAllText(d.FileName,store.Current().Raw);status.Text="当前规则已导出。";}catch(Exception ex){status.Text=ex.Message;}};button("Rollback").Click+=(s,e)=>{try{store.Rollback();refresh();changed();status.Text="已回退，重新扫描后生效。";}catch(Exception ex){status.Text=ex.Message;}};
  button("AddPortable").Click+=(s,e)=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="选择便携或自定义安装目录"})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){if(!settings.PortableDirectories.Contains(d.SelectedPath,StringComparer.OrdinalIgnoreCase))settings.PortableDirectories.Add(d.SelectedPath);settings.Save();refresh();status.Text="目录已添加，下次手动扫描时检查。";}};button("RemovePortable").Click+=(s,e)=>{var selected=portable.SelectedItem as string;if(selected!=null){settings.PortableDirectories.Remove(selected);settings.Save();refresh();}};
  button("ChooseRecovery").Click+=(s,e)=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="选择文件备份保存目录；其他盘可释放 C 盘空间"})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)text("RecoveryPath").Text=d.SelectedPath;};button("SaveRecovery").Click+=(s,e)=>{try{string p=Path.GetFullPath(text("RecoveryPath").Text);if(p.StartsWith("\\\\")||!Directory.Exists(p)||!Engine.SafeAncestors(Path.Combine(p,"probe")))throw new IOException("请选择可验证的本地现有目录");settings.RecoveryDirectory=p;settings.Save();changed();status.Text="备份位置已保存。";}catch(Exception ex){status.Text=ex.Message;}};
  button("RestoreFiles").Click+=async(s,e)=>{var d=new OpenFileDialog{Filter="澄净文件备份 (*.csbackup)|*.csbackup",Title="选择文件备份索引"};if(d.ShowDialog(w)!=true)return;if(MessageBox.Show(w,"恢复本机、本账户的文件备份，已有文件保留。", "恢复文件",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;restoring=true;button("RestoreFiles").IsEnabled=button("Purge").IsEnabled=false;status.Text="正在校验并恢复文件…";try{int restored=await Task.Run(()=>FileRecovery.Restore(d.FileName));status.Text="已恢复 "+restored+" 个文件；现有文件未覆盖。";}catch(Exception ex){status.Text="恢复停止："+ex.Message;}finally{restoring=false;button("RestoreFiles").IsEnabled=button("Purge").IsEnabled=true;}};
  button("Purge").Click+=(s,e)=>{var d=new OpenFileDialog{Filter="澄净文件备份 (*.csbackup)|*.csbackup",Title="选择要清空的备份"};if(d.ShowDialog(w)!=true)return;try{var entries=FileRecovery.Read(d.FileName);if(MessageBox.Show(w,"永久删除该批 "+entries.Count+" 个备份文件。此后不能从该备份恢复。", "清空备份",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;FileRecovery.Purge(d.FileName);status.Text="该批备份已清空。";}catch(Exception ex){status.Text=ex.Message;}};
  var tabs=FindTabs((DependencyObject)w.Content);if(preview!=null){if(tabs!=null)tabs.SelectedIndex=previewTab;w.ShowInTaskbar=false;w.ShowActivated=false;w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-10000;w.Top=-10000;w.Loaded+=(s,e)=>w.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ContextIdle,new Action(()=>{if(previewTab==1&&apps.Items.Count>0)apps.SelectedIndex=0;App.Render(w,preview);w.Close();}));}
  w.Closing+=(s,e)=>{if(updating){e.Cancel=true;updateStop.Cancel();status.Text="正在取消更新…";}if(restoring){e.Cancel=true;status.Text="正在恢复文件，请完成后关闭。";}};w.ShowDialog();
 }
 static TabControl FindTabs(DependencyObject node){var tabs=node as TabControl;if(tabs!=null)return tabs;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(node);i++){var found=FindTabs(System.Windows.Media.VisualTreeHelper.GetChild(node,i));if(found!=null)return found;}return null;}
}
}
